/* правила процентов и налога — настраиваются, лист 01 считается по ним */
const RULES={sales:5,prod:15,supply:3,taxVat:16,taxSimple:3,logistic:2};
function econ(o){
 const e=ENT[o.ent];const tax=Math.round(o.sum*(e.vat?RULES.taxVat:RULES.taxSimple)/100);
 const sales=Math.round(o.sum*RULES.sales/100);
 const gp=v=>o.sum-tax-sales-(v?o.fTmc:o.pTmc)-(v?o.fCrew:o.pCrew)-o.log;
 const prodP=Math.max(0,Math.round(gp(false)*RULES.prod/100)),prodF=Math.max(0,Math.round(gp(true)*RULES.prod/100));
 const supP=Math.round(o.pTmc*RULES.supply/100),supF=Math.round(o.fTmc*RULES.supply/100);
 const costP=o.pTmc+o.pCrew+o.log+prodP+supP,costF=o.fTmc+o.fCrew+o.log+prodF+supF;
 const profP=o.sum-tax-sales-costP,profF=o.sum-tax-sales-costF;
 return {tax,sales,prodP,prodF,supP,supF,costP,costF,profP,profF,debt:o.sum-o.recv,marg:pct(profF,o.sum),after:o.sum-tax};
}
