CARD.shop=()=>{const ws=WORKS.filter(w=>w.b===0);return [esc(SHOP.n),esc(SHOP.spec),`<div class="pan"><h3>Заказы цеха за сезон</h3>${ws.map(w=>`<div class="kv"><span>${oL(w.o)} · ${esc(w.n)}</span><b>${tg(w.agr)}</b></div>`).join('')}</div><div class="pan"><h3>Как считается</h3><p>Цех — внутренняя бригада: стоимость «за цех» ложится в себестоимость вида работ объекта, а плиты уходят из склада в цех и из цеха на объект двумя накладными. Станок Cedima — в инструмент-обороте.</p><div class="btns" style="justify-content:flex-start"><button class="bt p" onclick="closeM();go('shop')">Раздел «Цех»</button></div></div>`]};
