CARD.kp=n=>{const k=KPS.find(x=>x.n===n);return [esc(k.n)+' · '+esc(k.svc),esc(k.cl)+' · '+dl(k.d)+' · '+tg(k.v)+' · '+esc(k.mgr),`<div class="pan"><div class="kv"><span>Статус</span><b><span class="tag ${KST[k.st][1]}">${KST[k.st][0]}</span>${k.why?' · '+esc(k.why):''}</b></div><div class="kv"><span>Расчёт</span><b class="mono">${esc(k.calc)}</b></div><div class="kv"><span>Фото до начала</span><b>${esc(k.photo)}</b></div><div class="kv"><span>Файл КП</span><b class="mono">КП/2026/${esc(k.n)}.pdf</b></div>${k.o?`<div class="kv"><span>Объект</span><b>${oL(k.o)}</b></div>`:''}</div>
 <div class="pan"><h3>Из расчёта в договор</h3><p>Три позиции берутся из итогов расчёта: ТМЦ, работы, логистика. Виды работ со строк расчёта становятся планом объекта — с ценой клиенту и сметной стоимостью бригады.</p><div class="btns" style="justify-content:flex-start">${k.st==='won'?'<span class="tag g">договор заключён</span>':`<button class="bt p" onclick="closeM();toast('Договор из ${esc(k.n)}: выберите юрлицо → три позиции → объект и папки → задачи службам.')">Договор из КП</button><button class="bt" onclick="act('kp-remind')">Напомнить клиенту</button>`}</div></div>`]};
